import{_ as a,a as i,c as l,ac as o}from"./chunks/framework.BSuaGltH.js";const b=JSON.parse('{"title":"服务端技术与工具学习地图","description":"服务端语言、数据存储、消息、部署与监控工具分类","frontmatter":{"title":"服务端技术与工具学习地图","description":"服务端语言、数据存储、消息、部署与监控工具分类","sources":[{"repository":"jekyall_blog","file":"_posts/Dev/utils/2023-05-27-server.md","date":"Sat May 27 2023 11:32:25 GMT+0800 (中国标准时间)"}],"showdocs":{"topics":[{"id":"engineering","title":"编辑器与 IDE","link":"/topics/engineering/"}],"kind":"编辑器与IDE任务与配置","scope":"historical","audience":"general","group":"工程与工具","summary":"服务端语言、数据存储、消息、部署与监控工具分类","status":"active","related":[{"title":"编辑器与IDE：完整实践与解答","link":"/tools/developer-tools/engineering/practice/application","kind":"编辑器与IDE完整实践与解答","scope":"general","audience":"general"},{"title":"Jira Software 使用技巧与 JQL 搜索指南","link":"/tools/developer-tools/engineering/guide/jira-software","kind":"编辑器与IDE上手与对象","scope":"general","audience":"general"},{"title":"Jira Software 使用技巧与 JQL 搜索指南 · 1. Jira 能解决什么问题至5. JQL 语句结构","link":"/tools/developer-tools/engineering/guide/jira-software-part-01","kind":"编辑器与IDE上手与对象","scope":"general","audience":"general"},{"title":"Jira Software 使用技巧与 JQL 搜索指南 · 6. 可直接复制的 JQL至13. 官方参考","link":"/tools/developer-tools/engineering/guide/jira-software-part-02","kind":"编辑器与IDE上手与对象","scope":"general","audience":"general"},{"title":"Vim编辑与插件管理","link":"/tools/developer-tools/engineering/vim-editing-and-plugins","kind":"编辑器与IDE任务与配置","scope":"general","audience":"general"}],"prev":false,"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":false},"headers":[],"relativePath":"tools/developer-tools/engineering/reference/server.md","filePath":"tools/developer-tools/engineering/reference/server.md"}'),r={name:"tools/developer-tools/engineering/reference/server.md"};function t(n,e,p,s,c,d){return i(),l("div",null,[...e[0]||(e[0]=[o('<h1 id="服务端技术与工具学习地图" tabindex="-1">服务端技术与工具学习地图 <a class="header-anchor" href="#服务端技术与工具学习地图" aria-label="Permalink to &quot;服务端技术与工具学习地图&quot;">​</a></h1><p><span id="server"></span></p><blockquote><p>这是 2023 年整理的工具分类清单，未核验为当前选型推荐或产品能力对比。</p></blockquote><h2 id="程序员必备" tabindex="-1">程序员必备 <a class="header-anchor" href="#程序员必备" aria-label="Permalink to &quot;程序员必备&quot;">​</a></h2><blockquote><p>服务端</p></blockquote><h2 id="必备技术和工具" tabindex="-1">必备技术和工具 <a class="header-anchor" href="#必备技术和工具" aria-label="Permalink to &quot;必备技术和工具&quot;">​</a></h2><h2 id="编程语言" tabindex="-1">编程语言 <a class="header-anchor" href="#编程语言" aria-label="Permalink to &quot;编程语言&quot;">​</a></h2><ol><li><p>Java：Java 是应用最为广泛的服务端编程语言之一，它在企业级应用开发领域有广泛的应用。</p></li><li><p>Python：Python 具有简单易学、高效性和可扩展性等优点，在数据处理、机器学习等领域也非常流行。</p></li><li><p>Golang：Golang 是谷歌公司开发的现代编程语言，具有高并发性、高效性、易于编写和维护等优点，适合构建大型分布式系统。</p></li><li><p>JavaScript：JavaScript 是 Web 前端开发中不可缺少的语言，同时也可以用于编写服务端应用程序。Node.js 提供了一个服务器环境，使得 JavaScript 也可以被用来开发服务端程序。</p></li><li><p>C++：C++ 是一门强类型的编程语言，被广泛应用于高性能计算、游戏开发、操作系统、数据库等领域。</p></li><li><p>Rust：Rust 是一门安全而生的语言</p></li></ol><h2 id="web-框架" tabindex="-1">Web 框架 <a class="header-anchor" href="#web-框架" aria-label="Permalink to &quot;Web 框架&quot;">​</a></h2><ol><li><p>Java：Java 开发中最常用的 Web 框架是 Spring。Struts 也是 Web 框架；<a href="https://hibernate.org/orm/" target="_blank" rel="noopener noreferrer">Hibernate ORM</a> 和 <a href="https://mybatis.org/mybatis-3/" target="_blank" rel="noopener noreferrer">MyBatis</a> 主要用于持久化与数据访问，不属于同一类 Web 框架。</p></li><li><p>Python：Python 中常用的 Web 框架有 Django、Flask、Tornado、Pyramid 等。</p></li><li><p>Golang：Golang 中的 Web 框架也很多，常用的有 Gin、Echo、Beego、Martini 等。</p></li><li><p>JavaScript：JavaScript 作为一门跨平台的语言，被广泛应用于 Web 前后端开发。Node.js 支持的 Web 框架主要有 Express、Koa、Hapi 等。</p></li><li><p>Ruby：Ruby 开发中最常用的 Web 框架是 Ruby on Rails，它提供了一套完整的 MVC 架构，非常适合快速开发 Web 应用程序。</p></li></ol><h2 id="数据库" tabindex="-1">数据库 <a class="header-anchor" href="#数据库" aria-label="Permalink to &quot;数据库&quot;">​</a></h2><ol><li><p>关系型数据库：关系型数据库是最常见的存储数据的方式，常用的关系型数据库包括 MySQL、Oracle、PostgreSQL、Microsoft SQL Server 等。</p></li><li><p>NoSQL 数据库：NoSQL 数据库适合存储非结构化数据和大规模数据。常用的 NoSQL 数据库包括 MongoDB、Cassandra、Redis、Elasticsearch 等。</p></li><li><p>NewSQL 数据库：NewSQL 数据库是传统关系型数据库和分布式 NoSQL 数据库的混合体，旨在提供更好的可扩展性和高可用性。常用的 NewSQL 数据库有 CockroachDB、TiDB 等。</p></li><li><p>图形数据库：图形数据库适用于处理复杂的关系网络数据，通常使用基于图论的算法进行查询和存储。常用的图形数据库包括 Neo4j、ArangoDB 等。</p></li><li><p>时间序列数据库：时间序列数据库适用于存储时间相关的数据，如物联网设备数据、日志数据等。常用的时间序列数据库包括 InfluxDB、OpenTSDB 等。</p></li></ol><h2 id="缓存" tabindex="-1">缓存 <a class="header-anchor" href="#缓存" aria-label="Permalink to &quot;缓存&quot;">​</a></h2><ol><li><p>Redis：Redis 是一个基于内存的数据存储系统，可以用作缓存、消息队列和持久化存储等。它支持多种数据结构，如字符串、列表、哈希表等，并提供了丰富的操作命令。</p></li><li><p>Memcached：Memcached 是一个高性能的分布式内存缓存系统，适用于高并发读取、低并发写入的场景。它将数据存储在内存中，支持多线程操作，可以快速地存储和获取数据。</p></li><li><p>Guava Cache：Guava Cache 是 Google 的一个开源缓存库，提供了本地内存缓存功能，适用于小规模的应用程序。它支持自定义过期策略、最大缓存数量等参数配置。</p></li><li><p>Ehcache：Ehcache 是一个广泛使用的 Java 缓存框架，可以用于本地缓存或者分布式缓存，支持多种缓存策略，如 LRU、FIFO 等。</p></li><li><p>Caffeine：Caffeine 是一个 Java 缓存库，具有高性能、低延迟、简单易用等特点。它支持异步加载、过期时间设置、容量限制等功能。</p></li></ol><h2 id="消息队列" tabindex="-1">消息队列 <a class="header-anchor" href="#消息队列" aria-label="Permalink to &quot;消息队列&quot;">​</a></h2><ol><li><p>RabbitMQ：RabbitMQ 是一个开源的 AMQP（高级消息队列协议）实现，支持多种消息传输模式，如点对点、发布/订阅和请求/响应等。它具有高可靠性、高可扩展性和丰富的插件机制。</p></li><li><p>Apache Kafka：Apache Kafka 是一个高吞吐量、分布式的消息系统，适合处理大规模的日志数据和流数据。它具有低延迟、高可靠性、可伸缩性和多语言支持等特点。</p></li><li><p>ActiveMQ：ActiveMQ 是一个基于 JMS（Java 消息服务）协议的开源消息中间件。它支持多种传输协议，如 TCP、UDP、HTTP 和 WebSockets 等，并提供了多种语言客户端库。</p></li><li><p>RocketMQ：RocketMQ 是阿里巴巴公司自主研发的开源分布式消息中间件，具有高可用、高性能、高可扩展性等特点，支持多种消息协议和消息存储方式。</p></li><li><p>NSQ：NSQ 是由 Bitly 公司开发的分布式实时消息平台，具有高可靠性、易于部署和维护等特点，适合处理实时数据流。</p></li></ol><blockquote><p>除此之外，还有许多其他的消息队列方案，如 ZeroMQ、Redis 消息队列等</p></blockquote><h2 id="服务器" tabindex="-1">服务器 <a class="header-anchor" href="#服务器" aria-label="Permalink to &quot;服务器&quot;">​</a></h2><p>Node.js 的类别依据见<a href="https://nodejs.org/en/about" target="_blank" rel="noopener noreferrer">官方介绍</a>。</p><ol><li><p>Apache HTTP Server：Apache HTTP Server 是一个常用的开源 Web 服务器软件，可运行于多个操作系统平台上，如 Windows、Linux、Unix 等。它支持多种语言和通信协议，并提供了丰富的插件和模块。</p></li><li><p>Nginx：Nginx 是一个轻量级的高性能 Web 服务器和反向代理服务器，适用于处理静态文件、负载均衡、反向代理等任务。它具有低内存消耗、高并发连接等优点。</p></li><li><p>Tomcat：Tomcat 是一个常用的 Java Web 应用服务器，可以托管 Java Servlet 和 JSP 应用程序。它简单易用、开源免费，并且与 Spring 等框架集成良好。</p></li><li><p>Jetty：Jetty 是一个轻量级的 Java Web 服务器，具有高效、灵活、易于嵌入的特点。它支持多种 Web 标准和协议，并提供了多种 API 和插件。</p></li><li><p>Node.js：Node.js 是用于运行 JavaScript 的运行环境，编程语言仍是 JavaScript；可用它构建 Web 服务。它具有高性能、异步 I/O、事件驱动等优点，适合构建高并发的网络应用程序。</p></li></ol><blockquote><p>此外，还有许多其他的服务器软件，如 IIS、Caddy、Lighttpd 等</p></blockquote><h2 id="容器化技术" tabindex="-1">容器化技术 <a class="header-anchor" href="#容器化技术" aria-label="Permalink to &quot;容器化技术&quot;">​</a></h2><ol><li><p>Docker：Docker 是一种轻量级的容器化技术，可以将应用程序和依赖项打包成一个独立的容器，实现跨平台的部署。它具有快速启动、高效利用系统资源等优点，支持自动化构建、发布和运行应用程序。</p></li><li><p>Kubernetes：Kubernetes 是一种开源的容器编排引擎，用于管理容器化的应用程序和服务。它提供了多种功能，如自动负载均衡、自动扩缩容、滚动升级和回滚等。</p></li><li><p>Apache Mesos：Apache Mesos 是一种分布式系统内核，用于在集群中管理资源和调度任务。它支持多种框架和任务类型，如 Hadoop、Spark、Docker 等，并提供了多种 API 和工具。</p></li><li><p>LXD：LXD 是一个轻量级的系统容器技术，适用于高性能计算、虚拟化、云计算等领域。<a href="https://documentation.ubuntu.com/lxd/latest/" target="_blank" rel="noopener noreferrer">LXD</a> 管理系统容器与虚拟机；运行系统容器和硬件虚拟化是不同方式，不能统称为全系统模拟。</p></li><li><p>OpenShift：OpenShift 是一种基于 Kubernetes 的企业级容器化平台，提供了一整套应用程序、服务和解决方案。它支持多语言和多框架的应用程序开发、测试和部署，并提供了丰富的自动化工具。</p></li></ol><blockquote><p>除此之外，还有许多其他的容器化技术，如 Docker Compose、Docker Swarm、Mesosphere DC/OS 等</p></blockquote><h2 id="自动化部署工具" tabindex="-1">自动化部署工具 <a class="header-anchor" href="#自动化部署工具" aria-label="Permalink to &quot;自动化部署工具&quot;">​</a></h2><ol><li><p>Ansible：Ansible 是一种轻量级的自动化配置管理工具，可以用于配置服务器、应用程序和网络设备等。它支持多种操作系统和云平台，并使用 YAML 格式描述配置信息。</p></li><li><p>Jenkins：Jenkins 是一个开源的自动化构建和测试工具，可实现自动化编译、测试和部署等任务。它支持多种插件和扩展，如 Git、Docker、Kubernetes 等。</p></li><li><p>Puppet：Puppet 是一个流行的自动化配置管理工具，可用于管理多个服务器并保持一致性。它支持多种操作系统和云平台，并提供了丰富的模块和资源。</p></li><li><p>Chef：Chef 是另一种广泛使用的自动化配置管理工具，可用于自动化部署应用程序和管理基础架构。它支持多种操作系统和云平台，并提供了丰富的模块和资源。</p></li><li><p>SaltStack：SaltStack 是一种快速、灵活和可扩展的自动化配置管理工具，可用于远程执行命令、配置服务器和管理基础架构。它支持多种操作系统和云平台，并提供了分布式部署和多种通信协议。</p></li></ol><h2 id="日志收集工具" tabindex="-1">日志收集工具 <a class="header-anchor" href="#日志收集工具" aria-label="Permalink to &quot;日志收集工具&quot;">​</a></h2><ol><li><p>ELK Stack：ELK Stack 是一个由 Elastic 公司开发的日志管理平台，包括 Elasticsearch、Logstash 和 Kibana 三个组件。它可以采集、存储和分析各种类型的日志数据，并提供了丰富的查询和可视化功能。</p></li><li><p>Graylog：Graylog 是一种开源的日志管理平台，类似于 ELK Stack，但更加易于安装和配置。它支持多种输入来源、多种输出方式，以及强大的搜索和过滤功能。</p></li><li><p>Fluentd：Fluentd 是一种轻量级的日志收集和转发工具，支持多种日志格式和多种输出方式。它可以与 ELK Stack 或其他分布式系统集成，并提供了丰富的插件和扩展。</p></li><li><p>Splunk：Splunk 是一种商业化的日志管理和分析软件，可用于监控、搜索和分析各种类型的数据。它支持多种数据源和数据格式，并提供了丰富的查询和可视化功能。</p></li><li><p>Papertrail：Papertrail 是一种云端日志管理服务，可用于实时日志查看、搜索和过滤等任务。它支持多种日志来源和多种输出方式，并提供了通知和警报功能。</p></li></ol><h2 id="监控系统" tabindex="-1">监控系统 <a class="header-anchor" href="#监控系统" aria-label="Permalink to &quot;监控系统&quot;">​</a></h2><ol><li><p>Nagios：Nagios 是一种开源的系统和网络监控工具，可以用于监控主机、服务、网络设备等。它支持多种通信协议和插件，并提供了丰富的报警和通知功能。</p></li><li><p>Zabbix：Zabbix 是一种流行的企业级监控系统，可用于监控服务器性能、网络流量、应用程序状态等。它支持多种数据源和数据格式，并提供了图形化的界面和可定制的仪表板。</p></li><li><p>Prometheus：Prometheus 是一个开源的时序数据库和监控系统，适用于容器化环境和云原生应用程序。它使用 HTTP 协议采集指标数据，并提供了丰富的查询和告警规则。</p></li><li><p>Grafana：Grafana 是一种流行的开源数据可视化平台，可以与其他监控系统集成。它支持多种数据源和数据格式，并提供了可定制的仪表板和报表。</p></li><li><p>Sensu：Sensu 是一种轻量级的分布式监控和告警系统，可用于检测服务和基础设施故障。它提供了多种插件和扩展，可用于监控不同类型的应用程序和服务。</p></li></ol>',30)])])}const u=a(r,[["render",t]]);export{b as __pageData,u as default};
